 16	/**
 17	 * Whether this planet wants a wall at all, and how big: the size half of the defence decision.
 18	 *
 19	 * `DefenseCompositionPlanner` decides what shape the wall takes; this decides whether there is
 20	 * anything worth defending and how much. What a raider weighs is the pile on the planet and the
 21	 * production that accrues there while the account is away, both in the one currency the game prices
 22	 * everything in, and that value is what the wall is sized to. The doctrine never enters here: it
 23	 * picks the shape, not the size, so a Minimalist and a Bunker are handed the same size and build it
 24	 * differently.
 25	 *
 26	 * Two things decide the number, both host state the module already reads. Presence: the account's
 27	 * own `activity_band` is how often it looks in, so a band that visits once a day leaves a planet's
 28	 * output standing far longer than one that looks every few hours and is exposed to more of it.
 29	 * Contact: a pile only counts once the account has been seen -- an unmolested account spends its
 30	 * surplus rather than standing a wall against it (decision doctrine D10, spend-first) -- but once the
 31	 * host reports a hostile inbound there is no time left to spend it, so the whole pile joins what the
 32	 * wall must cover. The archetype is deliberately not an input: two miners with the same band and the
 33	 * same planet state want the same wall.
 34	 *
 35	 * The need is a value, not a unit count: how many units a wall of this worth is stays the
 36	 * composition planner's business, because the doctrine's ratio and the host's prices live there.
 37	 */
 38	class DefenseNeedEvaluator
 39	{
 40	    /** Metal-equivalent weights, the same ones the rest of the module prices production with. */
 41	    private const CRYSTAL_WEIGHT = 1.5;
 42	
 43	    private const DEUTERIUM_WEIGHT = 2.0;
 44	
 45	    private const HOURS_PER_DAY = 24.0;
 46	
 47	    public function evaluate(PlayerService $player, PlanetService $planet): ?DefenseNeed
 48	    {
 49	        $profile = AiProfile::query()->where('player_id', $player->getId())->first();
 50	        if ($profile === null) {
 51	            return null;
 52	        }
 53	
 54	        $inbound = $this->inbound($player);
 55	
 56	        // The ceiling outranks the exposure clock: a planet that already holds the wall the
 57	        // behaviour file caps wants nothing further, whatever the account's production would pile
 58	        // up while it is away. Exposure is unbounded, and left to it the account builds the whole
 59	        // account's wall on one planet.
 60	        if ($this->atCeiling($planet)) {
 61	            return null;
 62	        }
 63	
 64	        // What piles up before the account next looks at the planet, what is standing on it, plus the
 65	        // pile itself once a hostile is on its way and spending it is no longer an option.
 66	        // A raider weighs what stands on the planet as much as what the mines pile up: hulls left in
 67	        // orbit and the solar satellites a planet keeps for power are carried away by the same attack,
 68	        // so they are part of the exposure the wall is sized to. The ships come from the host's own
 69	        // collection, so a satellite, a cargo hull and a warship are all counted at the host's price
 70	        // with no hull named here.
 71	        $exposure = $this->hourlyProduction($planet) * $this->absenceHours($profile->activity_band)
 72	            + $this->unitValue($planet->getShipUnits());
 73	        if ($inbound) {
 74	            $exposure += $this->metalEquivalent($planet->getResources());
 75	        }
 76	
 77	        // A planet with no defence at all takes the file's floor before exposure is weighed: a young
 78	        // colony's output is near zero, so exposure alone leaves it naked beside the walled planets
 79	        // the same account already holds (measured live 30 Sep 2026: 7-8 planets at zero defence while
 80	        // one held the wall). One wall unit's worth is all this says; the doctrine still sizes it.
 81	        if ($this->standingUnits($planet) === 0) {
 82	            $floor = $this->minimumDeterrent();
 83	            if ($floor !== null && $exposure < $floor->defenceValue) {
 84	                return $floor;
 85	            }
 86	        }
 87	
 88	        // A wall already worth at least this much wants nothing further; the two planners agree on
 89	        // the value through this comparison and nowhere else.
 90	        if ($exposure <= $this->unitValue($planet->getDefenseUnits())) {
 91	            return null;
 92	        }
 93	
 94	        return app()->makeWith(DefenseNeed::class, [
 95	            'defenceValue' => $exposure,
 96	            'reason' => 'defense:need:' . $this->contact($inbound),
 97	            'protectedValue' => $exposure,
 98	            'currentDefenseValue' => $this->unitValue($planet->getDefenseUnits()),
 99	            'threatBand' => $this->contact($inbound),
100	            'intent' => $inbound ? 'reinforce' : 'hold',
101	        ]);
102	    }
103	
104	    /**
105	     * Whether this planet already holds the wall the behaviour file caps, built or paid for in the
106	     * yard. The yard counts because the host takes the whole price when the order is placed, so a
107	     * planet with the ceiling queued has bought it (measured live: 50.8M paid but unbuilt units on
108	     * grand while the planets read under the ceiling on built units alone).
109	     */
110	    private function atCeiling(PlanetService $planet): bool
111	    {
112	        $ceiling = $this->ceilingUnits();
113	
114	        if ($ceiling === null) {
115	            return false;
116	        }
117	
118	        return $this->standingUnits($planet) >= $ceiling;
119	    }
120	
121	    /**
122	     * The defence units this planet holds, built plus already ordered. Public because "this planet is
123	     * still bare" is the question the unit planner asks before it spreads the account's wall orders:
124	     * a planet whose first order is in the yard is no longer naked, so the next bare sibling gets the
125	     * next order instead of the same planet taking every one (measured live 2 Oct 2026: one planet
126	     * holding 21,084 units while 7-8 siblings sat at zero defence).
127	     */
128	    public function standingUnits(PlanetService $planet): int
129	    {
130	        return $planet->getDefenseUnits()->getAmount() + $this->pendingDefenseUnits($planet);
131	    }
132	
133	    /** Defence this planet has paid for and is waiting on, from the host's own unit queue. */
134	    private function pendingDefenseUnits(PlanetService $planet): int
135	    {
136	        $defenceObjectIds = array_map(
137	            static fn ($object): int => $object->id,
138	            ObjectService::getDefenseObjects()
139	        );
140	
141	        if ($defenceObjectIds === []) {
142	            return 0;
143	        }
144	
145	        return (int) UnitQueue::query()
146	            ->where('planet_id', $planet->getPlanetId())
147	            ->whereIn('object_id', $defenceObjectIds)
148	            ->where('processed', 0)
149	            ->sum('object_amount');
150	    }
151	
152	    /**
153	     * The ceiling on one planet's wall from the behaviour file, or null when the file states none.
154	     * The number is policy, so it lives there and not here; a file without it caps nothing.
155	     */
156	    private function ceilingUnits(): ?int
157	    {
158	        $parsed = Yaml::parseFile(module_path('AI', 'resources/behavior/defence-doctrines.yaml'));
159	        $units = is_array($parsed) ? ($parsed['standing_wall_ceiling']['units'] ?? null) : null;
160	
161	        return is_numeric($units) && (int) $units > 0 ? (int) $units : null;
162	    }
163	
164	    /**
165	     * The floor under the exposure-derived need for a planet that holds nothing, from the behaviour
166	     * file, or null when the file states none. The number is policy and the reason is its trace, so
167	     * both live there and not here.
168	     */
169	    private function minimumDeterrent(): ?DefenseNeed
170	    {
171	        $parsed = Yaml::parseFile(module_path('AI', 'resources/behavior/defence-doctrines.yaml'));
172	        $block = is_array($parsed) ? ($parsed['minimum_deterrent'] ?? null) : null;
173	        $value = is_array($block) ? ($block['value'] ?? null) : null;
174	        $reason = is_array($block) ? ($block['reason'] ?? null) : null;
175	
176	        if (! is_numeric($value) || (float) $value <= 0.0 || ! is_string($reason)) {
177	            return null;
178	        }
179	
180	        return app()->makeWith(DefenseNeed::class, [
181	            'defenceValue' => (float) $value,
182	            'reason' => $reason,
183	        ]);
184	    }
185	
186	    /**
187	     * How long the account leaves this planet alone between two visits.
188	     *
189	     * The activity band is how many times a day the account looks in, so the gap is a day divided by
190	     * that. A band with no value yet falls back to the middle of the range rather than disabling the
191	     * wall.
192	     */
193	    private function absenceHours(?AiActivityBand $band): float
194	    {
195	        return self::HOURS_PER_DAY / max(1, $band?->value ?? AiActivityBand::Regular->value);
196	    }
197	
198	    /**
199	     * Whether a visitor is already on the way: the host's own under-attack answer, so the module
200	     * keeps no mission-type list.
201	     */
202	    private function inbound(PlayerService $player): bool
203	    {
204	        return app()->makeWith(FleetMissionService::class, ['player' => $player])->currentPlayerUnderAttack();
205	    }
206	
207	    /** Names what the account has recently seen, so a trace can show why the wall grew. */
208	    private function contact(bool $inbound): string
209	    {
210	        return $inbound ? 'inbound' : 'unwatched';
211	    }
212	
213	    /** The planet's own output in the one currency, from the host's production figures. */
214	    private function hourlyProduction(PlanetService $planet): float
215	    {
216	        return $planet->getMetalProductionPerHour()
217	            + self::CRYSTAL_WEIGHT * $planet->getCrystalProductionPerHour()
218	            + self::DEUTERIUM_WEIGHT * $planet->getDeuteriumProductionPerHour();
219	    }
220	
221	    /** The metal-equivalent value of a unit collection, from the host's own raw prices. */
222	    private function unitValue(UnitCollection $units): float
223	    {
224	        $value = 0.0;
225	        foreach ($units->toArray() as $machineName => $amount) {
226	            $value += $this->metalEquivalent(ObjectService::getObjectRawPrice($machineName)) * $amount;
227	        }
228	
229	        return $value;
230	    }
231	
232	    private function metalEquivalent(Resources $resources): float
233	    {
234	        return $resources->metal->get()
235	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
236	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
237	    }
238	}

