    7	use Modules\AI\Models\AiProfile;
    8	use OGame\Factories\PlayerServiceFactory;
    9	use OGame\GameObjects\Models\Enums\GameObjectType;
   10	use OGame\Models\Resources;
   11	use OGame\Models\User;
   12	use OGame\Services\BuildingQueueService;
   13	use OGame\Services\ObjectService;
   14	use OGame\Services\PlanetService;
   15	use OGame\Services\PlayerService;
   16	use OGame\Services\ResearchQueueService;
   17	
   18	/**
   19	 * Answers one question about the account's own economy: is there a building or a technology it can
   20	 * legally queue now, and on which planet?
   21	 *
   22	 * Two things want a building. The chain wants the facility a later capability cannot exist without
   23	 * -- an account with no research lab can never research, and one with no shipyard can never own a
   24	 * ship -- and the economy wants the upgrade that repays itself fastest, or the storage that is about
   25	 * to overflow. The plan runs in two passes across the account's planets: first a warehouse that is
   26	 * about to overflow anywhere (it stops that planet producing, so it outranks every routine step on
   27	 * every other planet), then the routine economy planet by planet -- the energy a planet needs before
   28	 * it throttles, the chain's facilities, then the fastest-paying mine. The cross-planet storage pass
   29	 * is what keeps a full warehouse on one colony from waiting behind a routine mine on the homeworld.
   30	 *
   31	 * Both are only suggestions. Every gate is the host's own -- planet type, free queue space,
   32	 * requirements met against what is built *and* queued, and a price the planet can pay, which is the
   33	 * same set the building page shows a human -- so the module never restates an OGame rule. A target
   34	 * the host rejects is not an error but a fall-through: the planner tries the next one, which is what
   35	 * keeps a single impossible favourite from costing the account its whole build capability.
   36	 *
   37	 * Affordability is a real gate rather than a nicety: `BuildingQueueService::start()` cancels a queue
   38	 * item it cannot pay for, so publishing `build` while short of resources spends a queue slot and
   39	 * reports nothing at all.
   40	 */
   41	class QueueableBuildingPlanner
   42	{
   43	    /** The lab is one queue for the account, so its step has one slot beside the per-planet building steps. */
   44	    private const LAB_STEP = 'lab';
   45	
   46	    public function __construct(
   47	        private PlayerServiceFactory $playerServiceFactory,
   48	        private FacilityChain $facilityChain,
   49	        private EnergyCapacity $energyCapacity,
   50	        private EconomyUpgrades $economyUpgrades,
   51	        private ReserveFloor $reserveFloor,
   52	        private BuildingQueueService $buildingQueueService,
   53	        private ResearchQueueService $researchQueueService,
   54	    ) {
   55	    }
   56	
   57	    public function plan(int $playerId, ?PlayerService $player = null): QueueableBuilding|QueueableResearch|null
   58	    {
   59	        return $this->steps($playerId, $player, 1)[0] ?? null;
   60	    }
   61	
   62	    /**
   63	     * Every queue a player would fill in one login: at most one building per planet, because each planet
   64	     * pays from its own stock and has its own build queue, and at most one technology, because the
   65	     * lab is one queue for the account. The order is plan()'s, so the first step is the one plan()
   66	     * returns.
   67	     *
   68	     * @return list<QueueableBuilding|QueueableResearch>
   69	     */
   70	    public function steps(int $playerId, ?PlayerService $player = null, int $limit = PHP_INT_MAX): array
   71	    {
   72	        // An account the module does not manage has no policy to apply, so it gets no capability.
   73	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
   74	        if ($profile === null) {
   75	            return [];
   76	        }
   77	
   78	        // The module owns profile rows; the host owns accounts. A profile can outlive its account or
   79	        // be written by a fixture, and loading an account the host does not have throws -- so the
   80	        // precondition is asked here rather than discovered in the host service.
   81	        if (!User::query()->whereKey($playerId)->exists()) {
   82	            return [];
   83	        }
   84	
   85	        // Refresh every planet's live balance once: the candidate pass reads stored amounts and
   86	        // energy, and a balance read stale is exactly the balance the queue later cancels on. The
   87	        // refresh stays in memory -- the observation path must not write.
   88	        $planets = ($player ?? $this->playerServiceFactory->make($playerId, true))->planets->all();
   89	        foreach ($planets as $planet) {
   90	            $planet->updateResources(false);
   91	            $planet->updateResourceProductionStats(false);
   92	            $planet->updateResourceStorageStats(false);
   93	        }
   94	
   95	        $passes = $this->passes($profile);
   96	
   97	        // What every planet is holding back, once per session: reading it walks the same candidate
   98	        // lists the passes do, so asking again inside each pass would repeat a planet's whole economy.
   99	        // It is also what keeps this list honest: the cohort reads "buildable" from exactly these
  100	        // steps, so a planet whose pile the goal reserves must not be offered here -- otherwise the
  101	        // read-out says buildable while the account rightly saves, and the invariant flags a saver
  102	        // for behaving as designed.
  103	        $goals = [];
  104	        foreach ($planets as $planet) {
  105	            $goals[$planet->getPlanetId()] = $this->savingsGoal($planet, $profile);
  106	        }
  107	
  108	        $steps = [];
  109	        foreach ($passes as $candidates) {
  110	            foreach ($planets as $planet) {
  111	                if (count($steps) >= $limit) {
  112	                    return array_values($steps);
  113	                }
  114	
  115	                $steps = $this->withStep($steps, $planet, $profile, $candidates, $goals[$planet->getPlanetId()]);
  116	            }
  117	        }
  118	
  119	        return array_values($steps);
  120	    }
  121	
  122	    /**
  123	     * The candidate lists in the order the planner tries them. A warehouse about to overflow stops
  124	     * that planet producing, so its pass runs across every planet before any routine step; a full
  125	     * warehouse (E7) is a spend signal and comes next; then the routine economy: energy before it
  126	     * throttles, the chain's facilities, the fastest-paying mine. Public so a read-out explains a
  127	     * planet with the same lists the decision used.
  128	     *
  129	     * @return array<string, callable(PlanetService): list<BuildCandidate>>
  130	     */
  131	    public function passes(AiProfile $profile): array
  132	    {
  133	        return [
  134	            // A planet holding no defence while a sibling already stands a wall is past the
  135	            // account's opening with a sibling walled everywhere else: the facilities the wall
  136	            // itself waits on come before the economy, so the planet is not left naked behind a
  137	            // stock it is busy spending (QUAL-003).
  138	            'wall' => fn (PlanetService $planet): array => $this->facilityChain->wallPending($planet),
  139	            'storage' => fn (PlanetService $planet): array => $this->economyUpgrades->storage($planet, $profile),
  140	            'surplus' => fn (PlanetService $planet): array => $this->economyUpgrades->spendSurplus($planet, $profile),
  141	            'routine' => fn (PlanetService $planet): array => [
  142	                ...$this->energyCapacity->pending($planet),
  143	                ...$this->facilityChain->pending($planet),
  144	                ...$this->economyUpgrades->storageForPrice($planet, $profile),
  145	                ...$this->economyUpgrades->production($planet, $profile),
  146	            ],
  147	        ];
  148	    }
  149	
  150	    /**
  151	     * The build queue and the lab run side by side, so a planet's building and the account's one
  152	     * technology are separate steps: a planet whose best candidate is a technology still builds.
  153	     *
  154	     * @param array<int|string, QueueableBuilding|QueueableResearch> $steps
  155	     * @param callable(PlanetService): list<BuildCandidate> $pass
  156	     * @return array<int|string, QueueableBuilding|QueueableResearch>
  157	     */
  158	    private function withStep(array $steps, PlanetService $planet, AiProfile $profile, callable $pass, ?SavingsGoal $goal): array
  159	    {
  160	        $candidates = $pass($planet);
  161	        $isResearch = static fn (BuildCandidate $candidate): bool => ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research;
  162	
  163	        // The candidate list is in priority order, so whichever queue its first entry belongs to is tried first.
  164	        $queues = [$planet->getPlanetId() => false, self::LAB_STEP => true];
  165	        if ($candidates !== [] && $isResearch($candidates[0])) {
  166	            $queues = array_reverse($queues, true);
  167	        }
  168	
  169	        foreach ($queues as $key => $research) {
  170	            if (isset($steps[$key])) {
  171	                continue;
  172	            }
  173	
  174	            $step = $this->firstQueueable($planet, $profile, array_values(array_filter($candidates, static fn (BuildCandidate $candidate): bool => $isResearch($candidate) === $research)), $goal);
  175	            if ($step !== null) {
  176	                $steps[$key] = $step;
  177	            }
  178	        }
  179	
  180	        return $steps;
  181	    }
  182	
  183	    /**
  184	     * The first candidate this planet can actually queue, or null when none of them is legal.
  185	     *
  186	     * @param list<BuildCandidate> $candidates
  187	     */
  188	    private function firstQueueable(PlanetService $planet, AiProfile $profile, array $candidates, ?SavingsGoal $goal): QueueableBuilding|QueueableResearch|null
  189	    {
  190	        foreach ($candidates as $candidate) {
  191	            if (!$this->canSpendFor($planet, $goal, $candidate)) {
  192	                continue;
  193	            }
  194	
  195	            // Which queue takes a step is the host's object type, not this module's opinion: the
  196	            // chain hands over prerequisites, and a technology among them is research.
  197	            if (ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research) {
  198	                $research = $this->queueableResearch($planet, $candidate);
  199	                if ($research === null) {
  200	                    continue;
  201	                }
  202	
  203	                return $research;
  204	            }
  205	
  206	            $planetId = $planet->getPlanetId();
  207	            if (!$this->canQueue($planet, $candidate)) {
  208	                continue;
  209	            }
  210	
  211	            return app()->makeWith(QueueableBuilding::class, [
  212	                'planetId' => $planetId,
  213	                'buildingId' => $candidate->buildingId,
  214	                'reason' => $candidate->reason,
  215	            ]);
  216	        }
  217	
  218	        return null;
  219	    }
  220	
  221	    /**
  222	     * Whether the building queue will take this candidate on this planet right now.
  223	     *
  224	     * Public because "the building queue cannot answer this" is a question a second planner has to

