221	    /**
222	     * Whether the building queue will take this candidate on this planet right now.
223	     *
224	     * Public because "the building queue cannot answer this" is a question a second planner has to
225	     * ask: a planet that cannot buy capacity here has one other route, and the yard may only take it
226	     * when this says no. The gate itself stays in one place rather than being restated next to it.
227	     */
228	    public function canQueue(PlanetService $planet, BuildCandidate $candidate): bool
229	    {
230	        return $this->refusal($planet, $candidate) === null;
231	    }
232	
233	    /**
234	     * Which of the host's gates refuses this building here, or null when the planet can queue it.
235	     * The gates are asked in the order the building page asks them: planet type, free queue space,
236	     * met requirements, a balance it can pay and a field the building still fits in. Named, so a
237	     * planet that never builds says why instead of reading as idle.
238	     */
239	    public function refusal(PlanetService $planet, BuildCandidate $candidate): ?string
240	    {
241	        $object = ObjectService::getObjectById($candidate->buildingId);
242	        $machineName = $object->machine_name;
243	
244	        if (!ObjectService::objectValidPlanetType($machineName, $planet)) {
245	            return 'planet type';
246	        }
247	        if ($this->buildingQueueService->retrieveQueue($planet)->isQueueFull()) {
248	            return 'queue full';
249	        }
250	        if (!ObjectService::objectRequirementsMetWithQueue($machineName, $planet->getObjectLevel($machineName) + 1, $planet)) {
251	            return 'requirements';
252	        }
253	        if (!$planet->hasResources($this->withReserve($planet, ObjectService::getObjectPrice($machineName, $planet), ReserveFloor::ECONOMY_HOURS))) {
254	            return 'price plus reserve';
255	        }
256	        // `BuildingQueueService::start()` refuses a field-consuming building once the planet's fields
257	        // are used up, and a terraformer cannot rescue it because a terraformer consumes a field too.
258	        if ($object->consumesPlanetField && $planet->getBuildingCount() >= $planet->getPlanetFieldMax()) {
259	            return 'no free field';
260	        }
261	
262	        return null;
263	    }
264	
265	    /**
266	     * What this planet is saving for: the price plus reserve of the first economy step the planet is
267	     * short of, or null when it is not saving. A player mines while short, so anything else that spends
268	     * the same resource waits (the shipyard leaves the balance alone until the step is paid).
269	     */
270	    public function savingFor(PlanetService $planet, AiProfile $profile): ?Resources
271	    {
272	        $candidate = $this->savingCandidate($planet, $profile);
273	        if ($candidate === null) {
274	            return null;
275	        }
276	
277	        return $this->withReserve($planet, ObjectService::getObjectPrice(ObjectService::getObjectById($candidate->buildingId)->machine_name, $planet), ReserveFloor::ECONOMY_HOURS);
278	    }
279	
280	    /** The first step in the planner's own order this planet cannot yet pay for, or null when it can pay for all of them. */
281	    private function savingCandidate(PlanetService $planet, AiProfile $profile): ?BuildCandidate
282	    {
